source='''from collections import defaultdict, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    axes = {
        "row": lambda r, c: r,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: c - r,
    }
    stats = {}
    for axis, keyfn in axes.items():
        groups = defaultdict(Counter)
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    groups[keyfn(r, c)][color] += 1
        score = sum(max(counts.values()) ** 2 / sum(counts.values()) for counts in groups.values())
        stats[axis] = (score, groups)
    axis = max(stats, key=lambda a: stats[a][0])
    groups = stats[axis][1]

    # Drop very short duplicate-color traces when they are minor fragments of a
    # much longer trace of the same color. Unique colors remain useful clues.
    color_max = defaultdict(int)
    group_info = {}
    for k, counts in groups.items():
        color, count = counts.most_common(1)[0]
        group_info[k] = (color, count)
        color_max[color] = max(color_max[color], count)
    clues = {}
    for k, (color, count) in group_info.items():
        if count >= 0.2 * color_max[color]:
            clues[k] = color

    period = None
    for p in range(1, max(h, w) + 1):
        residues = {}
        valid = True
        for k, color in clues.items():
            residue = k % p
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            period = p
            pattern = [None] * p
            for residue, color in residues.items():
                pattern[residue] = color
            break
    if period is None:
        raise ValueError("could not infer pattern period")

    # A single omitted phase can be recovered from the repeated short motif
    # at the end of a sequence (as in the diagonal examples).
    missing = [i for i, value in enumerate(pattern) if value is None]
    for i in missing:
        if len(missing) == 1 and pattern[(i - 2) % period] is not None:
            pattern[i] = pattern[(i - 2) % period]
        else:
            known = [(j, value) for j, value in enumerate(pattern) if value is not None]
            if not known:
                pattern[i] = 0
            else:
                j, value = min(known, key=lambda pair: min((pair[0] - i) % period, (i - pair[0]) % period))
                pattern[i] = value

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if axis == "row":
                k = r
            elif axis == "sum":
                k = r + c
            else:
                k = c - r
            row.append(pattern[k % period])
        out.append(row)
    return out
'''
